/*
m_i = β a_i + (1-β) g_i
v_i = γ b_i + (1-γ) g_i²
s_i = -α (m_i/(1-β^t)) / (sqrt(v_i/(1-γ^t)) + ε)
r_i = -α sqrt(1-γ^t)/(1-β^t) m_i / (sqrt(v_i) + ε)

where

a_i ∈ ℝ
b_i ∈ ℝ
g_i ∈ ℝ
α ∈ ℝ
β ∈ ℝ
γ ∈ ℝ
ε ∈ ℝ
t ∈ ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    VectorD m;
    VectorD v;
    VectorD s;
    VectorD r;

    heartlib(
        const std::vector<double> & a,
        const std::vector<double> & b,
        const std::vector<double> & g,
        const double & α,
        const double & β,
        const double & γ,
        const double & ε,
        const double & t)
    {
        const long dim_0 = a.size();
        assert( b.size() == dim_0 );
        assert( g.size() == dim_0 );
        // m_i = β a_i + (1-β) g_i
        m.resize(dim_0);
        for( int i=1; i<=dim_0; i++){
            m[i-1] = β * a.at(i-1) + (1 - β) * g.at(i-1);
        }
        // v_i = γ b_i + (1-γ) g_i²
        v.resize(dim_0);
        for( int i=1; i<=dim_0; i++){
            v[i-1] = γ * b.at(i-1) + (1 - γ) * pow(g.at(i-1), 2);
        }
        // s_i = -α (m_i/(1-β^t)) / (sqrt(v_i/(1-γ^t)) + ε)
        s.resize(dim_0);
        for( int i=1; i<=dim_0; i++){
            s[i-1] = -α * (m[i-1] / DT((1 - pow(β, t)))) / DT((sqrt(v[i-1] / DT((1 - pow(γ, t)))) + ε));
        }
        // r_i = -α sqrt(1-γ^t)/(1-β^t) m_i / (sqrt(v_i) + ε)
        r.resize(dim_0);
        for( int i=1; i<=dim_0; i++){
            r[i-1] = -α * sqrt(1 - pow(γ, t)) / DT((1 - pow(β, t))) * m[i-1] / DT((sqrt(v[i-1]) + ε));
        }
    }
};

