function output = heartlib(a, b, g, alpha, beta, gamma, epsilon, t)
% output = heartlib(a, b, g, α, β, γ, ε, t)
%
%    m_i = β a_i + (1-β) g_i
%    v_i = γ b_i + (1-γ) g_i²
%    s_i = -α (m_i/(1-β^t)) / (sqrt(v_i/(1-γ^t)) + ε)
%    r_i = -α sqrt(1-γ^t)/(1-β^t) m_i / (sqrt(v_i) + ε)
%    
%    where
%    
%    a_i ∈ ℝ
%    b_i ∈ ℝ
%    g_i ∈ ℝ
%    α ∈ ℝ
%    β ∈ ℝ
%    γ ∈ ℝ
%    ε ∈ ℝ
%    t ∈ ℝ
%    
    a = reshape(a,[],1);
    b = reshape(b,[],1);
    g = reshape(g,[],1);

    dim_0 = size(a, 1);
    assert( size(a,1) == dim_0 );
    assert( size(b,1) == dim_0 );
    assert( size(g,1) == dim_0 );
    assert(numel(alpha) == 1);
    assert(numel(beta) == 1);
    assert(numel(gamma) == 1);
    assert(numel(epsilon) == 1);
    assert(numel(t) == 1);

    % m_i = β a_i + (1-β) g_i

    m = zeros(dim_0,1);
    for i = 1:dim_0
        m(i) = beta * a(i) + (1 - beta) * g(i);
    end
    % v_i = γ b_i + (1-γ) g_i²

    v = zeros(dim_0,1);
    for i = 1:dim_0
        v(i) = gamma * b(i) + (1 - gamma) * g(i).^2;
    end
    % s_i = -α (m_i/(1-β^t)) / (sqrt(v_i/(1-γ^t)) + ε)

    s = zeros(dim_0,1);
    for i = 1:dim_0
        s(i) = -alpha * (m(i) / (1 - beta.^t)) / (sqrt(v(i) / (1 - gamma.^t)) + epsilon);
    end
    % r_i = -α sqrt(1-γ^t)/(1-β^t) m_i / (sqrt(v_i) + ε)

    r = zeros(dim_0,1);
    for i = 1:dim_0
        r(i) = -alpha * sqrt(1 - gamma.^t) / (1 - beta.^t) * m(i) / (sqrt(v(i)) + epsilon);
    end
    output.m = m;
    output.v = v;
    output.s = s;
    output.r = r;
end

